module shift_register(
	input clk,
	input load,
	input [3:0] d,
	output reg [3:0] q);initial
		q = 4'b0000;

	always @(posedge clk)
		if (load)
			q <= d;
		else
			q <= {1'b0, q[3:1]};

endmodule

