module top_module (
	input clk,
	input areset,
	input x,
	output z);parameter IDLE=0, S1=1, S10=2, S101=3;
	reg [1:0] state;
	always @(posedge clk, posedge areset) begin
		if (areset)
			state <= IDLE;
		else begin
			case (state)
				IDLE: state <= x ? S1 : IDLE;
				S1: state <= x ? S1 : S10;
				S10: state <= x ? S101 : IDLE;
				S101: state <= x ? S1 : S10;
			endcase
		end
	end

	assign z = (state == S101);

endmodule

