module mux_4to1 (
    input [3:0] data0,
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    input [1:0] sel,
    output reg [3:0] out
);

    // Multiplexer logic
    always @(*) begin
        case(sel)
            2'b00: out = data0;
            2'b01: out = data1;
            2'b10: out = data2;
            2'b11: out = data3;
            default: out = 4'b0000;
        endcase
    end

endmodule

