module top_module(out,en,clk,rst);output [7:0] out;
	output en;
	input clk;
	input rst;
	reg [3:0] d1 = 9;
	reg [3:0] d0 = 9;
	reg en = 1;

	always@(posedge clk or posedge rst) begin
		if(rst) begin
			d1 = 9;
			d0 = 9;
			en = 1;
		end

		else if(d1 > 0 || d0 > 0) begin
			if(d0 == 0) begin
				d0 = 9;
				if(d1 == 0)
					d1 = 9;
				else
					d1 = d1 - 1;
			end
			else
				d0 = d0 - 1;
			en = 1;
		end

		else if(d1 == 0 && d0 == 0)
			en = 0;
	end
	assign out = {d1,d0};endmodule

