module top_module (
        input clk,
        input areset,
        input bit_in,
        output reg detected);parameter Start=2'b00, S1=2'b01, S2=2'b10;
	reg [1:0] state;
	always @(posedge clk, posedge areset) begin
		if (areset)
			state <= Start;
		else begin
			case (state)
				Start: state <= bit_in ? S1 : Start;
				S1: state <= bit_in ? S2 : Start;
				S2: state <= bit_in ? S2 : Start;
			endcase
		end
	end

	assign detected = (state == S2);

endmodule

