module johnson_counter_3bit(
    input clk,          // Chip clock signal.
    input rst_n,        // Active-low reset signal. Defined as 0 for chip reset; defined as 1 for reset signal inactive.

    output [2:0] count  // 3-bit count value.
);

reg [2:0] count_r; // Register to hold the count value.

// Johnson counter logic
always @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        count_r <= 3'b000; // Reset counter
    else
        count_r <= {~count_r[2], count_r[2:1]}; // Shift and feedback inverted last bit
end

assign count = count_r;

endmodule

