    .A(sum1),
    .B(carry_in),
    .sum(sum),
    .carry(carry2)
);

// OR gate for carry outputs
assign carry_out = carry1 | carry2;

endmodule

module half_adder(
    input wire A,
    input wire B,
    output wire sum,
    output wire carry
    );

assign sum = A ^ B;
assign carry = A & B;

