module gray_code_counter (
    input clk,
    input areset,
    input en,
    output reg [2:0] gray_out);

    reg [2:0] binary_count;

    always @(posedge clk or posedge areset) begin
        if (areset) begin
            binary_count <= 3'b000;
            gray_out <= 3'b000;
        end else if (en) begin
            binary_count <= binary_count + 1;
            gray_out <= (binary_count >> 1) ^ binary_count;
        end
    end
endmodule

