description:
Design a 2-to-4 priority encoder with enable functionality. When the enable signal is asserted, the module outputs a one-hot encoding of the priority determined by the 2-bit selection input (sel). The highest priority input corresponding to sel values will dictate which bit of the 16-bit output is set to high, while all other bits are low. If the enable signal is not asserted, the output defaults to a low state.
module top_module(
    input [1:0] sel,
    input enable,
    output reg [15:0] out
);

code:
module top_module(
    input [1:0] sel,
    input enable,
    output reg [15:0] out
);reg [1:0] priority_sel;

always @(*) begin
    if (enable) begin
        casez(sel)
            2'b00: priority_sel = 2'b00;
            2'b01: priority_sel = 2'b01;
            2'b10: priority_sel = 2'b10;
            2'b11: priority_sel = 2'b11;
        endcase
    end else begin
        priority_sel = 2'b00;
    end
end

always @(priority_sel) begin
    case (priority_sel)
        2'b00: out = 16'b0000000000000001;
        2'b01: out = 16'b0000000000000010;
        2'b10: out = 16'b0000000000000100;
        2'b11: out = 16'b0000000000001000;
    endcase
end

endmodule

