module top_module(
  input clk,
  input rst,
  input we,
  input [7:0] wa,
  input [38:0] wd,
  input re,
  input [7:0] ra,
  output reg [38:0] rd
);reg [38:0] regfile [255:0];

  // Reset and write operations
  always @(posedge clk) begin
    if (rst) begin
      // Reset each register in the regfile manually
      integer i;
      for (i = 0; i < 256; i = i + 1) begin
        regfile[i] <= 0;
      end
    end else begin
      if (we) begin
        regfile[wa] <= wd;
      end
    end
  end

  // Read operation
  always @(*) begin
    rd = (re) ? regfile[ra] : 0;
  end

endmodule

