  input [3:0] a,
  input [3:0] b,
  output reg [3:0] out
);

code:
module top_module(
  input [3:0] a,
  input [3:0] b,
  output reg [3:0] out
);always @* begin
    out[0] = ~(a[0] & b[0]) & (a[0] | b[0]);
    out[1] = ~(a[1] & b[1]) & (a[1] | b[1]);
    out[2] = ~(a[2] & b[2]) & (a[2] | b[2]);
    out[3] = ~(a[3] & b[3]) & (a[3] | b[3]);
  end

endmodule

