module top_module(clk, reset, tick);input clk, reset;
	output wire tick;
	reg [19:0] count;
	reg [19:0] n_count;

	assign tick = (count == 999999);

	always @ (posedge clk, posedge reset)
	   if(reset)
		   count <= 20'b0;
		else
		   count <= n_count;

	always @ (*)
	   n_count = (tick) ? 20'b0 : count + 20'b1;

endmodule

